class Solution {
public:
    bool predictTheWinner(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> dp(nums.begin(), nums.end());
        for (int len = 2; len <= n; ++len) {
            for (int l = 0; l + len <= n; ++l) {
                int r = l + len - 1;
                dp[l] = std::max(nums[l] - dp[l + 1], nums[r] - dp[l]);
            }
        }
        return dp[0] >= 0;
    }
};
